package com.example.reviewservice.controller;
import com.example.reviewservice.dto.request.SellerReplyRequest; import com.example.reviewservice.dto.response.*; import com.example.reviewservice.service.ReviewService; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.security.oauth2.jwt.Jwt; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequiredArgsConstructor @RequestMapping("/api/v1/reviews/seller") @PreAuthorize("hasAnyAuthority('ROLE_SELLER','SELLER')") public class SellerReviewController { private final ReviewService service; @GetMapping public ApiResponse<PageResponse<ProductReviewResponse>> mine(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="50")int size){return ApiResponse.<PageResponse<ProductReviewResponse>>builder().status(200).data(service.getSellerReviews(jwt.getSubject(),page,size)).build();} @PostMapping("/{id}/reply") public ApiResponse<ProductReviewResponse> reply(@AuthenticationPrincipal Jwt jwt,@PathVariable UUID id,@Valid @RequestBody SellerReplyRequest request){return ApiResponse.<ProductReviewResponse>builder().status(200).data(service.replySellerReview(jwt.getSubject(),id,request)).build();}}
